head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05203";
scwin.isurCd = "";          // 발행기관코드
scwin.isurNm = "";          // 발행기관명
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.FISCYY_DISTR_BASDD_TP_CD = "1";   // 결산기분배기준일구분 — 1: 결산기 (원본 신규 저장 값, §10 #3)
scwin.DSCL_FORM_CD = "68212A";          // 공시안내문 서식코드 — 결산기변경 안내공시
// 원본 : /lstproc/ULDSTF05203.gfm (결산기변경관리 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05202)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규: 회사의 현재 결산월일을 "변경전"에 채우고 "변경후"는 비워 둔다.
 *  - 저장: 검증(업무 중복 확인 포함) → 확인 → 예약 건 확인 → 채번 → 등록. 수정·삭제는 업무처리번호 기준.
 *  - 회사 담당 부서가 아닌 사용자는 처리 버튼이 모두 잠긴다.
 *  - 공시안내문작성(ULDSTF92024)·기안(ULDSTF92004)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #7).
 *  - API 명세 결함(select-one 블록이 다른 화면 것 등)은 결과서 §5 「명세 ↔ AS-IS 차이」대로 가정했다(§10 #1).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05203/ULDSTF05203.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    draft : "btn_Drft",         // [기안]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 11. 03
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 11. 03
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 달력 검사 바인딩 → 신규 준비(scwin.initNewForm) 또는 수정 조회 → 부서 잠금.
 * (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";          // AS-IS arr[0]
    scwin.isurNm = param.isurNm ?? "";          // AS-IS arr[1]
    scwin.bzProcsNo = param.bzProcsNo ?? "";    // AS-IS arr[4]

    // 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37)
    $c.date.checkCalendarFormat(ica_chgDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(ica_mktactEnforceDd, "yyyyMMdd");
    $c.date.compareFromToDate(ica_chgStatDd, ica_chgEndDd, ["최초 사업연도 시작일", "최초 사업연도 종료일"]);

    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 업무처리번호 유무로 신규 준비 또는 수정 조회
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await scwin.initNewForm();
    } else {
        await scwin.selectOne();
    }

    // 4) 담당 부서가 아니면 처리 버튼을 잠근다(원본 마지막 줄 buttonSet.setButtonDepCd). 버튼 상태를 정한 뒤에 둬야 잠금이 남는다.
    await $c.lc.setButtonDepCd(scwin.getIsurCd(), $c.session.getUserInfo() ?? {}, [btn_Save, btn_Update, btn_Delete, btn_Drft, btn_Dscl]);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 11. 03
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 11. 03
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 11. 03
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 11. 03
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.btn_Dscl_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Drft_onclick
 * @author Inswave
 * @date 2026. 11. 03
 * @description 기안 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Drft_onclick = async function (e) {
    try {
        await scwin.writeDraft();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05203.btn_Drft_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectCurrentMmdd
 * @author Inswave
 * @date 2026. 11. 03
 * @description 신규: 회사의 현재 결산월일을 "변경전" 목록에 채운다. (원본 fn_new_onload 의 DIV_IDX_DTL_FSC_BF + TRS_IDX_NEWSEL — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부 — 실패면 신규 준비를 멈춘다
 * @hidden N
 */
scwin.selectCurrentMmdd = async function () {
    const sbmOptions = {
        id : "sbm_selectCurrentMmdd",
        method : "get",
        action : "/api/listing/lstproc/stock/fiscal-year-change/select-current-acntcls-mmdd",
        // TODO: 명세 target 은 dlt_listbasyymmdd=body 로 정의 id(dlt_mmdd)와 다르다 — 정의 id 로 받는다 (§10 #1)
        target : "dlt_mmdd=body",
        isProcessMsg : false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert("현재 결산월일을 조회하지 못했습니다.");
        return false;
    }

    dlt_dtlBfList.setJSON(scwin.toBfRows(dlt_mmdd.getAllJSON()));
    return true;
};

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 11. 03
 * @description 수정: 업무처리번호로 마스터와 변경전·변경후를 조회하고, 시장조치시행일·공시여부로 버튼 상태를 정한다.
 * (원본 fn_read_sync 동기 3회 → 1회, dts_Mst OnLoadCompleted — §5.2)
 * @returns
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/stock/fiscal-year-change/select-one",
        // TODO: 명세 3번 블록의 요청·응답이 다른 화면(ELW) 것 — 요청 bzProcsNo, 응답은 2번 블록의 dma_one 정의로 가정 (§10 #1)
        target : "dma_one=body,dlt_dtlBfList=body.dtlBfList,dlt_dtlAfList=body.dtlAfList",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 버튼을 모두 잠근다 — 저장 뒤 재조회 실패면 신규 상태([저장] 활성)가 남아 같은 건을 다시 저장할 수 있다.
    if (!result.responseJSON?.success) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    scwin.fillAfRow();
    scwin.showMmdd();

    // 시장조치시행일이 오늘 이후면 update, 지났으면 error(기안만) → 미공시면 update 로 덮어쓴다(원본 순서, §4)
    $c.stf.setButtonSetWithDate(ica_mktactEnforceDd, false, "grpBtnBox", scwin.BTN_MAP);
    $c.stf.setButtonSetWithDate2(dma_one.get("disclsYn"), "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.checkMst
 * @author Inswave
 * @date 2026. 11. 03
 * @description 현재일 이후로 예약된 결산기변경 건이 있는지 확인한다. 있으면 MSG-0011 을 안내하고 false. (원본 fn_mst_check(dts_BZ_CHECK, "1") — §5.3)
 * pcc $c.lc.mstCheck 는 AS-IS URL·미선언 전역을 써서 쓰지 않는다(§8 #11).
 * @returns {Promise<Boolean>} 진행해도 되면 true
 * @hidden N
 */
scwin.checkMst = async function () {
    const sbmOptions = {
        id : "sbm_checkMst",
        method : "get",
        action : "/api/listing/lstproc/stock/fiscal-year-change/select-mst-check",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.getIsurCd() });
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    // TODO: 명세 응답은 예약 건 레코드(dma_one), 자매 화면은 boolean — 둘 다 "예약 건 있음"으로 본다 (§10 #4)
    const body = result.responseJSON.body;
    const hasMst = (body === true) || (body === "true")
        || (body !== null && typeof body === "object" && !$c.util.isEmpty(body.bzProcsNo));
    if (hasMst) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0011", ""));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 11. 03
 * @description 신규 저장(I)·수정(U). 마스터 값과 변경전·변경후 목록을 한 전문으로 보내고, 성공하면 다시 조회한다.
 * (원본 fn_save_trs + trs OnSuccess/OnFail — §5.6)
 * 목록은 복사본으로 만들어 dataList 는 건드리지 않는다(§8 #6).
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @param {String} bzProcsNo 업무처리번호 (신규는 채번한 값)
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/stock/fiscal-year-change/insert" : "/api/listing/lstproc/stock/fiscal-year-change/update",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 변경후 월일 입력값을 목록 첫 행으로 되돌린다(원본 binder 가 현재 행에 쓰던 값 — §6.2).
    scwin.applyAfMmdd();

    // TODO: 명세 5·6번 요청 keyInfo 가 깨져 있어 읽은 키로 보낸다 — 목록 열 정의도 없음 (§5 차이 #4, §10 #1)
    // TODO: fiscyyDistrBasddTpCd(원본 "1", 명세 주석의 TO-BE 값 '13')·LIST_BZ_TP_CD 231 — 서버가 정하는지 확인 (§10 #3)
    const requestData = {
        bzProcsNo : bzProcsNo,
        isurCd : scwin.getIsurCd(),
        fiscyyDistrBasddTpCd : dma_one.get("fiscyyDistrBasddTpCd") || scwin.FISCYY_DISTR_BASDD_TP_CD,
        chgDd : dma_one.get("chgDd"),
        mktactEnforceDd : dma_one.get("mktactEnforceDd"),
        fiscyyChgRsnCd : dma_one.get("fiscyyChgRsnCd"),
        remk : dma_one.get("remk"),
        fiscyyChgStrtDd : dma_one.get("fiscyyChgStrtDd"),
        fiscyyChgEndDd : dma_one.get("fiscyyChgEndDd"),
        dtlBfList : scwin.buildDtlList(dlt_dtlBfList, "1", bzProcsNo),
        dtlAfList : scwin.buildDtlList(dlt_dtlAfList, "2", bzProcsNo)
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, jobNm)) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 성공한 뒤에만 업무처리번호를 확정한다 — 실패한 신규 번호가 남지 않게(§8 #9).
    scwin.bzProcsNo = bzProcsNo;
    await scwin.selectOne();
};

/**
 * @method
 * @name scwin.deleteTrs
 * @author Inswave
 * @date 2026. 11. 03
 * @description 삭제. 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 목록을 다시 조회한다. (원본 TRS_IDX_DELETE + buttonSet.status "D" — §5.7)
 * @returns
 * @hidden N
 */
scwin.deleteTrs = async function () {
    const sbmOptions = {
        id : "sbm_deleteTrs",
        method : "post",
        action : "/api/listing/lstproc/stock/fiscal-year-change/delete",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, "삭제")) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 11. 03
 * @description 신규 준비. 마스터를 비우고 회사를 표시한 뒤, 현재 결산월일을 "변경전"에 채우고 "변경후" 빈 행을 두고 [저장]만 켠다.
 * (원본 fn_new_onload + dts_Mst/dts_DtlAf OnLoadCompleted — §3, §1.4 업무 1)
 * @returns
 * @hidden N
 */
scwin.initNewForm = async function () {
    dma_one.setEmptyValue();
    dma_mmdd.setEmptyValue();
    dlt_dtlBfList.removeAll();
    dlt_dtlAfList.removeAll();

    // 신규는 부모 값으로 회사를 표시한다 (수정은 조회 응답 값 — §8 #7).
    dma_one.set("isurCd", scwin.isurCd);
    dma_one.set("isurNm", scwin.isurNm);

    // 현재 결산월일을 못 받으면 변경전이 빈 채로 저장되므로 멈추고 버튼을 잠근다.
    if (!await scwin.selectCurrentMmdd()) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }
    scwin.fillAfRow();
    scwin.showMmdd();

    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 11. 03
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다. (§6.1)
 *  1) 변경후 필수  2) 변경일·시장조치시행일 필수·날짜 (공통 검증)  3) 시장조치시행일은 익일 이후
 *  4) 변경사유 필수, 기타 2000 byte (공통 검증)  5) 같은 업무 중복 입력 확인 (업무공통)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const afMmdd = String(dma_mmdd.get("basMmddAf") ?? "");
    if (afMmdd === "") {
        await $c.win.alert("[변경후]를  선택해주세요");
        ibx_basMmDdAf.focus();
        return false;
    }
    // 원본 마스크(MM월DD일)는 4자리를 다 채워야 했다 — maxlength 는 상한뿐이라 덜 채운 값을 막는다(§8 #5).
    if (afMmdd.length !== 4) {
        await $c.win.alert("[변경후]를 월·일 4자리로 입력하세요.\n\n예 : 12월31일 -> 1231");
        ibx_basMmDdAf.focus();
        return false;
    }

    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            ica_chgDd : { required : true, format : "date", name : "변경일" },
            ica_mktactEnforceDd : { required : true, format : "date", name : "시장조치시행일" }
        }
    };
    if (!await $c.validate.validateDataCollect(grp_item, dateOptions)) return false;

    // 시장조치시행일은 익일 이후 (원본 checkDdTm("DD", …, false)) — 원본 순서대로 변경사유보다 먼저 본다.
    if (dma_one.get("mktactEnforceDd") <= scwin.curDate) {
        await $c.win.alert("[시장조치시행일]을 익일 이후로 입력하세요.");
        ica_mktactEnforceDd.focus();
        return false;
    }

    const etcOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            sbx_fiscyyChgRsnCd : { required : true, name : "변경사유" },
            txa_remk : { maxLengthB : 2000, name : "기타" }
        }
    };
    if (!await $c.validate.validateDataCollect(grp_item, etcOptions)) return false;

    // TODO: 변경 후 최초 사업연도 시작·종료일은 필수 표시가 있으나 원본도 검증하지 않음 (§8 #8, §10 #9)

    // 같은 회사·변경일로 처리 중인 업무가 있는지 (원본 fn_check_bz_doubleinput — 둘째 인자는 원본대로 변경일, §5.5)
    // TODO: pcc checkBzDoubleInput 결함(회사코드 키 isuCd, 응답에 disclsProcsDdtm 이 없으면 항상 false) — 배포 전 확인 (§10 #9)
    return await $c.lc.checkBzDoubleInput(scwin.getIsurCd(), dma_one.get("chgDd"), scwin.bzProcsNo, $c.lc.glb.LIST_BZ_TP_CD_231);
};

/**
 * @method
 * @name scwin.toBfRows
 * @author Inswave
 * @date 2026. 11. 03
 * @description 현재 결산월일 응답(결산월일1·2)을 변경전 목록 행으로 바꾼다. 빈 값은 뺀다. (§5.1, §10 #1)
 * @param {Array} rows dlt_mmdd 행 목록
 * @returns {Array} 변경전 목록 행
 * @hidden N
 */
scwin.toBfRows = function (rows) {
    return rows
        .flatMap(row => [row.basMmdd, row.basMmdd2])
        .filter(mmdd => !$c.util.isEmpty(mmdd))
        .map(mmdd => ({ basMmdd : mmdd }));
};

/**
 * @method
 * @name scwin.fillAfRow
 * @author Inswave
 * @date 2026. 11. 03
 * @description 변경후 목록이 비어 있으면 입력할 빈 행 1개를 둔다. (원본 dts_DtlAf OnLoadCompleted 의 AddRow)
 * @returns
 * @hidden N
 */
scwin.fillAfRow = function () {
    if (dlt_dtlAfList.getRowCount() === 0) dlt_dtlAfList.insertRow();
};

/**
 * @method
 * @name scwin.showMmdd
 * @author Inswave
 * @date 2026. 11. 03
 * @description 변경전·변경후 목록 첫 행의 결산월일을 입력칸(dma_mmdd)에 옮긴다. (원본 bnd_DtlBf·bnd_DtlAf 가 현재 행을 잇던 것 — §6.2)
 * @returns
 * @hidden N
 */
scwin.showMmdd = function () {
    const firstMmdd = (dataList) => (dataList.getRowCount() > 0) ? (dataList.getCellData(0, "basMmdd") ?? "") : "";

    dma_mmdd.set("basMmddBf", firstMmdd(dlt_dtlBfList));
    dma_mmdd.set("basMmddAf", firstMmdd(dlt_dtlAfList));
};

/**
 * @method
 * @name scwin.applyAfMmdd
 * @author Inswave
 * @date 2026. 11. 03
 * @description 변경후 입력칸 값을 변경후 목록 첫 행으로 되돌린다(행이 없으면 1행 추가). 둘째 행부터는 그대로 둔다. (§6.2)
 * @returns
 * @hidden N
 */
scwin.applyAfMmdd = function () {
    scwin.fillAfRow();
    dlt_dtlAfList.setCellData(0, "basMmdd", dma_mmdd.get("basMmddAf") ?? "");
};

/**
 * @method
 * @name scwin.buildDtlList
 * @author Inswave
 * @date 2026. 11. 03
 * @description 저장 전문의 변경전(1)·변경후(2) 목록을 만든다. 일련번호는 변경전 1부터, 변경후 13부터. 원본처럼 빈 행도 그대로 보낸다.
 * (원본 fn_save_trs 의 두 루프 — BYBZPROCS_SEQ 변경전 i, 변경후 i + 12)
 * @param {Object} dataList 대상 dataList (dlt_dtlBfList / dlt_dtlAfList)
 * @param {String} chgBfafTpCd 변경전후구분코드 1: 변경전, 2: 변경후
 * @param {String} bzProcsNo 업무처리번호
 * @returns {Array} 전송할 행 목록
 * @hidden N
 */
scwin.buildDtlList = function (dataList, chgBfafTpCd, bzProcsNo) {
    const seqBase = (chgBfafTpCd === "2") ? 12 : 0;

    return dataList.getAllJSON().map((row, i) => ({
        ...row,
        bzProcsNo : bzProcsNo,
        bybzprocsSeq : seqBase + i + 1,
        isurCd : scwin.getIsurCd(),
        chgBfafTpCd : chgBfafTpCd
    }));
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 11. 03
 * @description 저장·삭제 응답 판정. 통신 결과가 성공이 아니면 안내하고 false. 안내 문구는 응답 resultMessage, 없으면 MSG-A002.
 * 명세에 응답 정의가 없어 success 로만 판정한다(§5.6, §10 #5).
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    if (result.responseJSON?.success) return true;

    const msg = result.responseJSON?.body?.resultMessage;
    await $c.win.alert($c.util.isEmpty(msg) ? $c.stf.getMessageParam("MSG-A002", jobNm) : msg);
    return false;
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 11. 03
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내 문자열로 만든다. (§5.4)
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    const res = await $c.stf.getNewBzProcNo();
    const value = (res !== null && typeof res === "object") ? res.body : res;
    return String(value ?? "");
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 11. 03
 * @description 신규 저장. 검증(업무 중복 확인 포함) → 확인 → 예약 건 확인 → 채번 → 등록 순서 (원본 fn_save — §6.6, §1.4 업무 2)
 * 채번이 확인보다 뒤라서 취소한 건에는 번호가 소비되지 않는다.
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    if (!await scwin.checkMst()) return;

    // TODO: 명세 5번은 신규 시 서버 채번이라 적었다 — 지금은 원본대로 화면 채번 (§10 #2)
    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    await scwin.saveTrs(scwin.trJob, bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 11. 03
 * @description 수정. 검증 → 확인 → 수정 순서 (원본 fn_update — §6.7, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob, scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 11. 03
 * @description 삭제. 시장안내공시 승인 여부를 확인하고, 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.8, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // 승인된 공시가 있으면 삭제할 수 없다(원본 fn_check_delete_discls). pcc 가 target 을 문자열로 조립하므로 dataMap id 를 넘긴다(§5.8).
    if (!await $c.lc.checkDeleteDiscls("dma_bzCheck", scwin.bzProcsNo)) return;

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.deleteTrs();
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 11. 03
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..2] 와 데이터셋 3개다. (§6.4)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    return {
        formCd : scwin.DSCL_FORM_CD,            // AS-IS arr[0]
        bzProcsNo : scwin.bzProcsNo,            // AS-IS arr[1]
        isurCd : scwin.getIsurCd(),             // AS-IS arr[2]
        mst : [dma_one.getJSON()],              // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
        dtl2 : dlt_dtlBfList.getAllJSON(),      // AS-IS CopyDataSet(dts_DtlBf, param_dts2)
        dtl3 : dlt_dtlAfList.getAllJSON()       // AS-IS CopyDataSet(dts_DtlAf, param_dts3)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 11. 03
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 돌려받는 값은 없다. (원본 fn_dscl — §6.4, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 735,
        height : 815,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 11. 03
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.4, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 를 채운다(원본도 3칸)
 * @param {Object} dltIsu 92024 의 종목 dataList (원본도 넘기지 않음)
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (변경전)
 * @param {Object} dlt3 92024 의 원천 자료 3 (변경후)
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;

    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.dtl2);
    scwin.fillDataList(dlt3, data.dtl3);

    return arr.length;
};

/**
 * @method
 * @name scwin.getIsurCd
 * @author Inswave
 * @date 2026. 11. 03
 * @description 전문에 넣을 회사코드. 수정은 조회 응답 값, 신규는 부모가 넘긴 값이다. (§8 #7)
 * @returns {String} 회사코드
 * @hidden N
 */
scwin.getIsurCd = function () {
    return dma_one.get("isurCd") || scwin.isurCd;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 11. 03
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.writeDraft
 * @author Inswave
 * @date 2026. 11. 03
 * @description 기안문작성 팝업을 업무처리번호와 함께 열고 닫힐 때까지 기다린다. (원본 fn_drft — §6.5)
 * pcc $c.lc.popFindDraft 는 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @returns
 * @hidden N
 */
scwin.writeDraft = async function () {
    const options = {
        id : "ULDSTF92004",
        popupName : "기안문작성",
        width : 888,
        height : 730,
        type : "pageFramePopup"
    };

    // TODO: 기안 팝업 전환본이 없어 경로·수신 키(bzProcsNo)는 가정 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92004.xml", options, { bzProcsNo : scwin.bzProcsNo });
};
